}

fn print(x: Int) {
    print_str(int_to_str(x))
}

fn print_str(s: Str) {
    let stdout = std_io_stdout()
    write(stdout, s)
}

fn int_to_str(n: Int) -> Str {
    format("%d", n)
}

fn write(stdout: StdOut, s: Str) {
    stdout.write_str(s)
}

fn std_io_stdout() -> StdOut {
    std_io_stdout_locked(std_io_stdout_lock())
}

fn std_io_stdout_locked(stdout: StdOutLock) -> StdOut {
