fn to_string(n: Int) -> Str {
    let mut digits = vec()
    let mut number = n
    while number > 0 {
        digits.push(number % 10)
        number = number / 10
    }
    let mut result = vec()
    for digit in digits.iter().rev() {
        result.push(to_char(digit))
    }
    Str(result)
}

fn to_char(n: Int) -> Str {
    if n == 0 {
        return Str("0")
    }
    let mut number = n
    let mut result = vec()
    while number > 0 {
        let digit = number % 10
        result.push(if digit < 10 { to_char(digit) } else { to_char(digit - 10 + 65) })
        number = number / 10
    }
    Str(result)
}

